     5630:                 return -1;
     5631:             datasize = (uint64_t)typewidth * dp->tdir_count;
     5632:             if (!(tif->tif_flags & TIFF_BIGTIFF))
     5633:             {
     5634:                 if (datasize <= 4)
     5635:                     datasize = 0;
     5636:             }
     5637:             else
